/* ============================================================
   MEMORY FAMILIA — capa de datos y motor de tablero
   ============================================================
   Modelo de persona (RTDB, nodo /personas/{id}):
     { nombre, sexo:'H'|'M', padreId, madreId, parejaId, grupoHermanos, foto }
   - hermanos  -> se DERIVAN (mismo padreId o mismo madreId)
   - grupoHermanos -> EXCEPCIÓN: hermanos cuyos padres no están en la base.
     Misma etiqueta = hermanos. Úsalo solo cuando no haya padres que registrar.
   - hijos     -> se DERIVAN (invirtiendo padreId/madreId)
   - parejaId  -> siempre bidireccional (se fuerza al guardar)
   - foto      -> opcional (dataURL base64). Si falta, la carta usa el nombre.
   ============================================================ */

/* ---------- 1. CONFIGURACIÓN FIREBASE -----------------------
   Pega aquí el firebaseConfig de tu proyecto.
   Si lo dejas vacío, la app arranca en MODO DEMO (datos de ejemplo
   en memoria/localStorage). Útil para probar sin tocar Firebase.  */
export const FIREBASE_CONFIG = {
  apiKey: "",
  authDomain: "",
  databaseURL: "",
  projectId: "",
  storageBucket: "",
  messagingSenderId: "",
  appId: ""
};

const USAR_FIREBASE = !!FIREBASE_CONFIG.databaseURL;

/* ---------- 2. MODOS DE JUEGO ------------------------------ */
export const MODOS = {
  personal:  { etiqueta: "La misma persona", grupo: 2, color: "amb",  pista: "Empareja cada persona consigo misma." },
  hermanos:  { etiqueta: "Hermanos",         grupo: 2, color: "verd", pista: "Empareja hermanos (comparten padre o madre)." },
  padrehijo: { etiqueta: "Padre / hijo",     grupo: 2, color: "viol", pista: "Empareja cada persona con su padre o su madre." },
  pareja:    { etiqueta: "Pareja",           grupo: 2, color: "rosa", pista: "Empareja a cada persona con su pareja." },
  trio:      { etiqueta: "Trío familiar",    grupo: 3, color: "azul", pista: "Reúne padre, madre e hijo. Voltea tres cartas." }
};

export const TAMANOS_PAREJA = [4, 6, 8, 12, 15];   //  8 / 12 / 16 / 24 / 30 cartas
export const TAMANOS_TRIO   = [5, 6, 7];           // 15 / 18 / 21 cartas

/* ---------- 3. CARGA / GUARDADO ---------------------------- */
let _fb = null;

async function firebase() {
  if (_fb) return _fb;
  const [{ initializeApp }, rtdb] = await Promise.all([
    import("https://www.gstatic.com/firebasejs/10.12.0/firebase-app.js"),
    import("https://www.gstatic.com/firebasejs/10.12.0/firebase-database.js")
  ]);
  const app = initializeApp(FIREBASE_CONFIG);
  _fb = { db: rtdb.getDatabase(app), ...rtdb };
  return _fb;
}

const LS_KEY = "memoriaFamiliar.demo";
let _demo = null;

function demoPersonas() {
  if (_demo) return _demo;
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (raw) { _demo = JSON.parse(raw); return _demo; }
  } catch (e) { /* localStorage no disponible: seguimos en memoria */ }
  _demo = semilla();
  return _demo;
}

function guardarDemo() {
  try { localStorage.setItem(LS_KEY, JSON.stringify(_demo)); } catch (e) {}
}

export async function cargarPersonas() {
  if (!USAR_FIREBASE) return { ...demoPersonas() };
  const { db, ref, get, child } = await firebase();
  const snap = await get(child(ref(db), "personas"));
  return snap.exists() ? snap.val() : {};
}

export async function guardarPersona(id, persona) {
  const p = { ...persona };
  ["padreId", "madreId", "parejaId", "grupoHermanos", "foto"].forEach(k => { if (!p[k]) delete p[k]; });
  if (Array.isArray(p.fotos) && p.fotos.length === 0) delete p.fotos;

  if (!USAR_FIREBASE) {
    const d = demoPersonas();
    d[id] = p;
    // pareja bidireccional
    Object.keys(d).forEach(k => { if (d[k].parejaId === id && k !== p.parejaId) delete d[k].parejaId; });
    if (p.parejaId && d[p.parejaId]) d[p.parejaId].parejaId = id;
    guardarDemo();
    return;
  }
  const { db, ref, update, get, child } = await firebase();
  const todas = (await get(child(ref(db), "personas"))).val() || {};
  const cambios = { [`personas/${id}`]: p };
  Object.keys(todas).forEach(k => {
    if (todas[k].parejaId === id && k !== p.parejaId) cambios[`personas/${k}/parejaId`] = null;
  });
  if (p.parejaId) cambios[`personas/${p.parejaId}/parejaId`] = id;
  await update(ref(db), cambios);
}

export async function borrarPersona(id) {
  if (!USAR_FIREBASE) {
    const d = demoPersonas();
    delete d[id];
    Object.values(d).forEach(p => {
      ["padreId", "madreId", "parejaId"].forEach(k => { if (p[k] === id) delete p[k]; });
    });
    guardarDemo();
    return;
  }
  const { db, ref, update, get, child } = await firebase();
  const todas = (await get(child(ref(db), "personas"))).val() || {};
  const cambios = { [`personas/${id}`]: null };
  Object.entries(todas).forEach(([k, p]) => {
    ["padreId", "madreId", "parejaId"].forEach(campo => {
      if (p[campo] === id) cambios[`personas/${k}/${campo}`] = null;
    });
  });
  await update(ref(db), cambios);
}

export const nuevoId = () => "p" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
export const esDemo = () => !USAR_FIREBASE;

/* Fotos de una persona (soporta modelo antiguo 'foto' y nuevo 'fotos[]'). */
export const fotosDe = p => p.fotos && p.fotos.length ? p.fotos : (p.foto ? [p.foto] : []);
export const fotoAzar = p => { const f = fotosDe(p); return f.length ? f[(Math.random() * f.length) | 0] : null; };

/* ---------- 3bis. RANKING ---------------------------------
   Un ranking independiente por combinación modo + nº de grupos:
   /ranking/{modo}_{n}/{pushId} = { jugador, seg, intentos, ts }
   Se ordena por TIEMPO (seg); los intentos solo desempatan.
   ----------------------------------------------------------- */
const LS_RANK = "memoriaFamiliar.ranking";

function rankingLocal() {
  try { return JSON.parse(localStorage.getItem(LS_RANK) || "{}"); } catch (e) { return {}; }
}

export async function guardarMarca(clave, marca) {
  const m = { jugador: String(marca.jugador).slice(0, 24), seg: marca.seg, intentos: marca.intentos };
  if (!USAR_FIREBASE) {
    const r = rankingLocal();
    (r[clave] = r[clave] || []).push({ ...m, ts: Date.now() });
    try { localStorage.setItem(LS_RANK, JSON.stringify(r)); } catch (e) {}
    return;
  }
  const { db, ref, push, set, serverTimestamp } = await firebase();
  await set(push(ref(db, `ranking/${clave}`)), { ...m, ts: serverTimestamp() });
}

export async function cargarRanking(clave, limite = 20) {
  let arr;
  if (!USAR_FIREBASE) {
    arr = rankingLocal()[clave] || [];
  } else {
    const { db, ref, get, query, orderByChild, limitToFirst } = await firebase();
    const snap = await get(query(ref(db, `ranking/${clave}`), orderByChild("seg"), limitToFirst(limite)));
    arr = snap.exists() ? Object.values(snap.val()) : [];
  }
  return arr.sort((a, b) => a.seg - b.seg || a.intentos - b.intentos).slice(0, limite);
}

/* ---------- 4. PARENTESCOS --------------------------------- */
export const sonHermanos = (a, b) =>
  a.id !== b.id && (
    (!!a.padreId && a.padreId === b.padreId) ||
    (!!a.madreId && a.madreId === b.madreId) ||
    (!!a.grupoHermanos && a.grupoHermanos === b.grupoHermanos)
  );

export const esProgenitorDe = (p, h) => h.padreId === p.id || h.madreId === p.id;

export const sonPareja = (a, b) =>
  a.id !== b.id && a.parejaId === b.id && b.parejaId === a.id;

/** ¿Existe relación del modo entre dos personas distintas? */
export function relacionados(modo, a, b) {
  if (a.id === b.id) return false;
  switch (modo) {
    case "personal":  return false;
    case "hermanos":  return sonHermanos(a, b);
    case "padrehijo": return esProgenitorDe(a, b) || esProgenitorDe(b, a);
    case "pareja":    return sonPareja(a, b);
    default:          return false;
  }
}

/** ¿Estas 3 personas forman padre + madre + hijo? */
export function esTrio(a, b, c) {
  for (const [h, x, y] of [[a, b, c], [b, a, c], [c, a, b]]) {
    if (!h.padreId || !h.madreId) continue;
    const padres = new Set([h.padreId, h.madreId]);
    if (padres.has(x.id) && padres.has(y.id) && x.id !== y.id) return true;
  }
  return false;
}

/* ---------- 5. GENERADOR DE TABLERO -------------------------
   Dos invariantes que HAY que cumplir o el juego es incorrecto:
   (I1) Cada persona aparece como máximo una vez en el tablero.
   (I2) No existe ninguna combinación de cartas del tablero, distinta
        de los grupos elegidos, que también sea una pareja/trío válida.
   (I2) es la que se olvida siempre. Ejemplo: 4 hermanos en el tablero
   formando 2 parejas -> A-C también sería "hermanos" y el jugador
   acertaría, pero el juego le diría que ha fallado.
   ------------------------------------------------------------ */

const barajar = a => { const x = [...a]; for (let i = x.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0;[x[i], x[j]] = [x[j], x[i]]; } return x; };

/** Lista de todos los grupos candidatos (pares o tríos) del modo. */
export function gruposCandidatos(modo, lista) {
  const g = [];
  if (modo === "personal") return lista.map(p => [p, p]);
  if (modo === "trio") {
    const porId = new Map(lista.map(p => [p.id, p]));
    for (const h of lista) {
      const pa = porId.get(h.padreId), ma = porId.get(h.madreId);
      if (pa && ma) g.push([h, pa, ma]);
    }
    return g;
  }
  for (let i = 0; i < lista.length; i++)
    for (let j = i + 1; j < lista.length; j++)
      if (relacionados(modo, lista[i], lista[j])) g.push([lista[i], lista[j]]);
  return g;
}

/** Validación completa (I2) por fuerza bruta. Coste máximo: C(21,3)=1330. */
function tableroValido(modo, grupos) {
  if (modo === "personal") return true;
  const cartas = grupos.flat();
  const grupoDe = new Map();
  grupos.forEach((g, k) => g.forEach(p => grupoDe.set(p.id, k)));

  if (modo === "trio") {
    for (let i = 0; i < cartas.length; i++)
      for (let j = i + 1; j < cartas.length; j++)
        for (let k = j + 1; k < cartas.length; k++) {
          const mismo = grupoDe.get(cartas[i].id) === grupoDe.get(cartas[j].id)
                     && grupoDe.get(cartas[j].id) === grupoDe.get(cartas[k].id);
          if (!mismo && esTrio(cartas[i], cartas[j], cartas[k])) return false;
        }
    return true;
  }
  for (let i = 0; i < cartas.length; i++)
    for (let j = i + 1; j < cartas.length; j++) {
      const mismo = grupoDe.get(cartas[i].id) === grupoDe.get(cartas[j].id);
      if (!mismo && relacionados(modo, cartas[i], cartas[j])) return false;
    }
  return true;
}

/**
 * Genera un tablero de n grupos. Devuelve array de grupos (cada grupo = array de personas)
 * o null si la base de datos no da para tanto.
 */
export function generarTablero(modo, n, personas) {
  const lista = Object.entries(personas).map(([id, p]) => ({ id, ...p }));

  if (modo === "personal") {
    if (lista.length < n) return null;
    return barajar(lista).slice(0, n).map(p => [p, p]);
  }

  const candidatos = gruposCandidatos(modo, lista);
  for (let intento = 0; intento < 400; intento++) {
    const usados = new Set();
    const sel = [];
    for (const g of barajar(candidatos)) {
      if (g.some(p => usados.has(p.id))) continue;
      const prueba = [...sel, g];
      if (!tableroValido(modo, prueba)) continue;
      sel.push(g);
      g.forEach(p => usados.add(p.id));
      if (sel.length === n) return sel;
    }
  }
  return null;
}

/** Máximo nº de grupos que admite la BD en este modo (para bloquear tamaños imposibles). */
export function capacidad(modo, personas) {
  const lista = Object.entries(personas).map(([id, p]) => ({ id, ...p }));
  if (modo === "personal") return lista.length;
  const candidatos = gruposCandidatos(modo, lista);
  let mejor = 0;
  for (let intento = 0; intento < 60; intento++) {
    const usados = new Set(); const sel = [];
    for (const g of barajar(candidatos)) {
      if (g.some(p => usados.has(p.id))) continue;
      const prueba = [...sel, g];
      if (!tableroValido(modo, prueba)) continue;
      sel.push(g); g.forEach(p => usados.add(p.id));
    }
    if (sel.length > mejor) mejor = sel.length;
  }
  return mejor;
}

/** Texto de la relación de un grupo acertado (se muestra al emparejar). */
export function etiquetaRelacion(modo, grupo) {
  const [a, b, c] = grupo;
  switch (modo) {
    case "personal":  return "la misma persona";
    case "hermanos":  return "hermanos";
    case "pareja":    return "pareja";
    case "trio":      return "padre · madre · hijo";
    case "padrehijo": {
      const prog = esProgenitorDe(a, b) ? a : b;
      const hijo = prog === a ? b : a;
      const rel = prog.sexo === "M" ? "madre" : "padre";
      return `${prog.nombre} es ${rel} de ${hijo.nombre}`;
    }
  }
  return "";
}

/* ============================================================
   JUEGO 2 — ORDENA POR EDAD
   ============================================================ */
export const TAMANOS_EDAD_FACIL = [6, 9, 12, 15, 18];
export const TAMANOS_EDAD_DIFICIL = [9, 12, 15, 18];
export const tamanosEdad = dif => dif === "dificil" ? TAMANOS_EDAD_DIFICIL : TAMANOS_EDAD_FACIL;

const anioDe = p => p.nacimiento ? parseInt(p.nacimiento.slice(0, 4)) : null;
// valor aproximado para ordenar (año + fracción de mes/día si se conoce)
function aprox(p) {
  const s = p.nacimiento; if (!s) return null;
  const y = +s.slice(0, 4);
  const m = s.length >= 7 ? +s.slice(5, 7) : 7;      // mes medio si falta
  const d = s.length === 10 ? +s.slice(8, 10) : 15;  // día medio si falta
  return y + (m - 1) / 12 + (d - 1) / 365;
}
/** ¿Se puede afirmar con CERTEZA que a es anterior/posterior a b? 0 = incierto. */
function ciertoOrden(a, b) {
  const ya = +a.nacimiento.slice(0, 4), yb = +b.nacimiento.slice(0, 4);
  if (ya !== yb) return Math.sign(ya - yb);
  const ma = a.nacimiento.length >= 7 ? +a.nacimiento.slice(5, 7) : null;
  const mb = b.nacimiento.length >= 7 ? +b.nacimiento.slice(5, 7) : null;
  if (ma && mb && ma !== mb) return Math.sign(ma - mb);
  const da = a.nacimiento.length === 10 ? +a.nacimiento.slice(8, 10) : null;
  const db = b.nacimiento.length === 10 ? +b.nacimiento.slice(8, 10) : null;
  if (ma && mb && ma === mb && da && db && da !== db) return Math.sign(da - db);
  return 0; // no se puede asegurar el orden
}

export function personasConEdad(personas) {
  return Object.entries(personas).map(([id, p]) => ({ id, ...p })).filter(p => p.nacimiento && p.nacimiento.length >= 4);
}

const _baraja = a => { const x = [...a]; for (let i = x.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0;[x[i], x[j]] = [x[j], x[i]]; } return x; };

/** Devuelve n personas ordenables con certeza. dif: 'facil' (gaps grandes) | 'dificil' (gaps pequeños). */
export function generarTableroEdad(dif, n, personas) {
  const L = personasConEdad(personas).sort((a, b) => aprox(a) - aprox(b));
  if (L.length < n) return null;
  const certeza = seq => seq.every((p, i) => i === 0 || ciertoOrden(seq[i - 1], p) < 0);

  for (let intento = 0; intento < 500; intento++) {
    let sel;
    if (dif === "dificil") {
      // ventana consecutiva: edades muy próximas
      const ini = (Math.random() * (L.length - n + 1)) | 0;
      sel = L.slice(ini, ini + n);
    } else {
      // reparto en n tramos: edades bien separadas
      sel = [];
      const paso = L.length / n;
      for (let k = 0; k < n; k++) {
        const lo = Math.floor(k * paso), hi = Math.floor((k + 1) * paso);
        sel.push(L[lo + ((Math.random() * Math.max(1, hi - lo)) | 0)]);
      }
    }
    if (new Set(sel.map(p => p.id)).size === n && certeza(sel)) {
      // el jugador recibe las cartas BARAJADAS; el orden correcto es 'sel'
      return { correcto: sel, cartas: _baraja(sel) };
    }
  }
  return null;
}

export function capacidadEdad(personas) {
  return personasConEdad(personas).length;
}

/* ============================================================
   JUEGO 3 — ENCUENTRA AL IMPOSTOR   (panel-relativo)
   La pregunta se resuelve mirando SOLO el panel:
   - "sin hermanos": hay grupos de hermanos completos + 1 solitario.
   - "sin pareja":   hay parejas completas + 1 suelto.
   Siempre hay exactamente UN impostor.
   ============================================================ */
export const PANELES = [5, 10];               // nº de paneles por ronda
export const TAMANOS_IMPOSTOR = [9, 12, 15, 18]; // cartas por panel (múltiplos de 3)

const apellido = p => {
  const t = p.nombre.trim().split(/\s+/);
  return t.length > 1 ? t[1] : t[0];
};
const anioNac = p => (p.nacimiento && p.nacimiento.length >= 4) ? +p.nacimiento.slice(0, 4) : null;
const mesNac = p => (p.nacimiento && p.nacimiento.length >= 7) ? p.nacimiento.slice(5, 7) : null;

/* Componentes de hermandad (cada persona con al menos un hermano) */
function familiasHermanos(L) {
  // agrupar por progenitor compartido y por grupoHermanos → cliques de hermanos
  const grupos = {};
  const push = (clave, p) => { (grupos[clave] = grupos[clave] || []).push(p); };
  L.forEach(p => {
    if (p.padreId) push("pa:" + p.padreId, p);
    else if (p.madreId) push("ma:" + p.madreId, p);
    if (p.grupoHermanos) push("gh:" + p.grupoHermanos, p);
  });
  // devolver solo cliques de 2+; dedup por conjunto de ids
  const vistos = new Set(), out = [];
  for (const arr of Object.values(grupos)) {
    if (arr.length < 2) continue;
    const key = arr.map(p => p.id).sort().join(",");
    if (vistos.has(key)) continue; vistos.add(key); out.push(arr);
  }
  return out;
}

const _panel = (tipo, texto, normales, impostor) => ({
  tipo, texto,
  cartas: _baraja([...normales.map(p => ({ ...p, impostor: false })), { ...impostor, impostor: true }])
});

/* Catálogo de preguntas. dif: 'facil' | 'dificil'. N = cartas del panel.
   Cada generador devuelve {tipo, texto, cartas} o null. El 'tipo' sirve para
   no repetir la misma clase de pregunta dentro de una ronda. */
function construirPanel(N, dif, personas) {
  const L = Object.entries(personas).map(([id, p]) => ({ id, ...p }));
  const need = N - 1;
  const generadores = [];
  const MES = ["", "enero", "febrero", "marzo", "abril", "mayo", "junio", "julio", "agosto", "septiembre", "octubre", "noviembre", "diciembre"];

  /* --- SIN HERMANOS (panel-relativo) --- */
  {
    const cliques = familiasHermanos(L);
    if (cliques.length) generadores.push(() => {
      for (let t = 0; t < 120; t++) {
        const usados = new Set(); const elegidos = [];
        let restante = need;
        const disp = _baraja(cliques);
        if (restante % 2 === 1) {
          const tri = disp.find(g => g.filter(p => !usados.has(p.id)).length >= 3);
          if (!tri) continue;
          _baraja(tri).filter(p => !usados.has(p.id)).slice(0, 3).forEach(p => { elegidos.push(p); usados.add(p.id); });
          restante -= 3;
        }
        for (const g of disp) {
          if (restante < 2) break;
          const libres = g.filter(p => !usados.has(p.id));
          if (libres.length >= 2) { libres.slice(0, 2).forEach(p => { elegidos.push(p); usados.add(p.id); }); restante -= 2; }
        }
        if (restante !== 0) continue;
        const solit = _baraja(L).find(p => !usados.has(p.id) && !elegidos.some(q => sonHermanos(p, q)));
        if (solit) return _panel("hermanos", "¿Quién no tiene hermanos? (mira el panel)", elegidos, solit);
      }
      return null;
    });
  }

  /* --- SIN PAREJA (panel-relativo) --- */
  if (need % 2 === 0) {
    const parejas = [];
    const hecho = new Set();
    L.forEach(p => {
      if (p.parejaId && personas[p.parejaId] && !hecho.has(p.id) && !hecho.has(p.parejaId)) {
        parejas.push([p, { id: p.parejaId, ...personas[p.parejaId] }]);
        hecho.add(p.id); hecho.add(p.parejaId);
      }
    });
    if (parejas.length >= need / 2) generadores.push(() => {
      for (let t = 0; t < 80; t++) {
        const sel = _baraja(parejas).slice(0, need / 2);
        const usados = new Set(sel.flat().map(p => p.id));
        const normales = sel.flat();
        const solit = _baraja(L).find(p => !usados.has(p.id) && (!p.parejaId || !usados.has(p.parejaId)));
        if (solit) return _panel("pareja", "¿Quién no tiene pareja? (mira el panel)", normales, solit);
      }
      return null;
    });
  }

  /* --- HIJO DE X: grupo de hijos de madres/padres DISTINTOS + 1 hijo de la persona preguntada --- */
  {
    // progenitores (con nombre conocido) que tienen al menos un hijo
    const hijosDe = {};   // idProgenitor -> [hijos]
    L.forEach(p => {
      for (const k of ["padreId", "madreId"]) if (p[k] && personas[p[k]]) (hijosDe[p[k]] = hijosDe[p[k]] || []).push(p);
    });
    const progenitores = Object.keys(hijosDe);
    if (progenitores.length >= need + 1) generadores.push(() => {
      for (let t = 0; t < 120; t++) {
        // elegir progenitor "diana" (el de la pregunta) con >=1 hijo
        const diana = _baraja(progenitores)[0];
        const nombreDiana = personas[diana].nombre;
        const impostor = _baraja(hijosDe[diana])[0];   // hijo de la diana = respuesta
        // normales: 1 hijo de cada uno de need progenitores DISTINTOS (ni la diana),
        // y que NO sean hijos de la diana
        const otros = _baraja(progenitores.filter(id => id !== diana));
        const normales = []; const usados = new Set([impostor.id]);
        for (const prog of otros) {
          if (normales.length >= need) break;
          const cand = _baraja(hijosDe[prog]).find(h => !usados.has(h.id) && h.padreId !== diana && h.madreId !== diana);
          if (cand) { normales.push(cand); usados.add(cand.id); }
        }
        if (normales.length === need)
          return _panel("hijo_de", `¿Quién es hijo o hija de ${nombreDiana}?`, normales, impostor);
      }
      return null;
    });
  }

  /* --- MÁS JOVEN / MAYOR --- */
  {
    const conEdad = L.filter(p => anioNac(p));
    if (conEdad.length >= N) {
      const extremo = joven => () => {
        for (let t = 0; t < 200; t++) {
          const g = _baraja(conEdad).slice(0, N).sort((a, b) => anioNac(a) - anioNac(b));
          if (new Set(g.map(anioNac)).size !== g.length) continue;
          const ext = joven ? g[g.length - 1] : g[0];
          const vecino = joven ? anioNac(g[g.length - 2]) : anioNac(g[1]);
          if (Math.abs(anioNac(ext) - vecino) >= 4)
            return _panel(joven ? "joven" : "mayor", joven ? "¿Quién es el más joven?" : "¿Quién es el mayor?", joven ? g.slice(0, -1) : g.slice(1), ext);
        }
        return null;
      };
      generadores.push(extremo(true));
      generadores.push(extremo(false));
    }
  }

  /* --- DIFÍCIL: preguntas por fecha --- */
  if (dif === "dificil") {
    const conAnio = L.filter(p => anioNac(p));
    const conMes = L.filter(p => mesNac(p));
    const conDia = L.filter(p => p.nacimiento && p.nacimiento.length === 10);
    const diaN = p => +p.nacimiento.slice(8, 10);
    const add = g => generadores.push(g);

    // NO nació en tal mes
    const porMes = {};
    conMes.forEach(p => { (porMes[mesNac(p)] = porMes[mesNac(p)] || []).push(p); });
    const mesesNo = Object.entries(porMes).filter(([, a]) => a.length >= need);
    if (mesesNo.length) add(() => {
      const [mm, gente] = _baraja(mesesNo)[0];
      const fuera = conMes.filter(p => mesNac(p) !== mm);
      if (!fuera.length) return null;
      return _panel("mes_no", `¿Quién no nació en ${MES[+mm]}?`, _baraja(gente).slice(0, need), _baraja(fuera)[0]);
    });

    // SÍ nació en tal mes (afirmativa): grupo de otros meses + 1 del mes preguntado
    const mesesSi = Object.keys(porMes).filter(mm => conMes.filter(p => mesNac(p) !== mm).length >= need && porMes[mm].length >= 1);
    if (mesesSi.length) add(() => {
      const mm = _baraja(mesesSi)[0];
      const dentro = _baraja(porMes[mm])[0];
      const fuera = _baraja(conMes.filter(p => mesNac(p) !== mm)).slice(0, need);
      if (fuera.length < need) return null;
      return _panel("mes_si", `¿Quién nació en ${MES[+mm]}?`, fuera, dentro);
    });

    // AÑO EXACTO: "¿Quién es de 1943?" con gente de una franja de ±5 años alrededor
    const porAnio = {};
    conAnio.forEach(p => { (porAnio[anioNac(p)] = porAnio[anioNac(p)] || []).push(p); });
    const aniosDiana = Object.keys(porAnio).map(Number);
    if (aniosDiana.length) add(() => {
      for (let t = 0; t < 60; t++) {
        const Y = aniosDiana[(Math.random() * aniosDiana.length) | 0];
        const dentro = _baraja(porAnio[Y])[0];
        const franja = _baraja(conAnio.filter(p => anioNac(p) >= Y - 5 && anioNac(p) <= Y + 5 && anioNac(p) !== Y));
        if (franja.length >= need) return _panel("anio", `¿Quién nació en ${Y}?`, franja.slice(0, need), dentro);
      }
      return null;
    });

    // DÍA EXACTO: "¿Quién nació el día 27?" con gente de otros días
    const porDia = {};
    conDia.forEach(p => { (porDia[diaN(p)] = porDia[diaN(p)] || []).push(p); });
    const diasDiana = Object.keys(porDia).map(Number).filter(d => conDia.filter(p => diaN(p) !== d).length >= need);
    if (diasDiana.length) add(() => {
      const D = diasDiana[(Math.random() * diasDiana.length) | 0];
      const dentro = _baraja(porDia[D])[0];
      const fuera = _baraja(conDia.filter(p => diaN(p) !== D)).slice(0, need);
      if (fuera.length < need) return null;
      return _panel("dia_exacto", `¿Quién nació el día ${D}?`, fuera, dentro);
    });

    // SIGLO XX / XXI (impostor pegado a la frontera del 2000)
    const cercaFrontera = (pool, arriba) => pool.sort((a, b) => arriba ? anioNac(a) - anioNac(b) : anioNac(b) - anioNac(a)).slice(0, 1);
    add(() => {
      const xx = conAnio.filter(p => anioNac(p) <= 1999).sort((a, b) => anioNac(b) - anioNac(a)).slice(0, need);
      const cerca = cercaFrontera(conAnio.filter(p => anioNac(p) >= 2000 && anioNac(p) <= 2004), true);
      if (xx.length === need && cerca.length) return _panel("siglo", "¿Quién no es del siglo XX?", _baraja(xx), cerca[0]);
      return null;
    });
    add(() => {
      const xxi = conAnio.filter(p => anioNac(p) >= 2000).sort((a, b) => anioNac(a) - anioNac(b)).slice(0, need);
      const cerca = cercaFrontera(conAnio.filter(p => anioNac(p) >= 1995 && anioNac(p) <= 1999), false);
      if (xxi.length === need && cerca.length) return _panel("siglo", "¿Quién no es del siglo XXI?", _baraja(xxi), cerca[0]);
      return null;
    });

    // DÉCADA (impostor de una década contigua)
    const porDecada = {};
    conAnio.forEach(p => { const d = Math.floor(anioNac(p) / 10) * 10; (porDecada[d] = porDecada[d] || []).push(p); });
    const decadasOk = Object.entries(porDecada).filter(([, a]) => a.length >= need).map(([d, a]) => [+d, a]);
    if (decadasOk.length) add(() => {
      const [dec, gente] = decadasOk[(Math.random() * decadasOk.length) | 0];
      const contigua = conAnio.filter(p => { const d = Math.floor(anioNac(p) / 10) * 10; return d === dec - 10 || d === dec + 10; });
      const lejana = conAnio.filter(p => Math.floor(anioNac(p) / 10) * 10 !== dec);
      const impostor = _baraja(contigua.length ? contigua : lejana)[0];
      if (!impostor) return null;
      return _panel("decada", `¿Quién no nació en la década de los ${String(dec).slice(2).padStart(2, "0")}?`, _baraja(gente).slice(0, need), impostor);
    });

    // PRIMEROS 10 DÍAS (un solo tipo 'dia10' para que no salgan las dos variantes juntas)
    const temprano = conDia.filter(p => diaN(p) <= 10);
    const tardio = conDia.filter(p => diaN(p) >= 11);
    if (temprano.length >= need && tardio.length) add(() =>
      _panel("dia10", "¿Quién no nació en los 10 primeros días del mes?", _baraja(temprano).slice(0, need), _baraja(tardio)[0]));
    if (tardio.length >= need && temprano.length) add(() =>
      _panel("dia10", "¿Quién nació en los 10 primeros días del mes?", _baraja(tardio).slice(0, need), _baraja(temprano)[0]));

    // GENERACIÓN (impostor de generación contigua)
    const GEN = [
      { n: "la Generación Silenciosa", a: 1900, b: 1945 },
      { n: "la generación Boomer", a: 1946, b: 1964 },
      { n: "la Generación X", a: 1965, b: 1980 },
      { n: "la generación Millennial", a: 1981, b: 1996 },
      { n: "la Generación Z", a: 1997, b: 2012 },
      { n: "la Generación Alfa", a: 2013, b: 2030 }
    ];
    const enGen = (p, g) => anioNac(p) >= g.a && anioNac(p) <= g.b;
    const gensOk = GEN.map((g, i) => ({ g, i, gente: conAnio.filter(p => enGen(p, g)) })).filter(x => x.gente.length >= need);
    if (gensOk.length) add(() => {
      const { g, i, gente } = gensOk[(Math.random() * gensOk.length) | 0];
      const contig = conAnio.filter(p => (GEN[i - 1] && enGen(p, GEN[i - 1])) || (GEN[i + 1] && enGen(p, GEN[i + 1])));
      const lejos = conAnio.filter(p => !enGen(p, g));
      const impostor = _baraja(contig.length ? contig : lejos)[0];
      if (!impostor) return null;
      return _panel("generacion", `¿Quién no es de ${g.n} (nacidos entre ${g.a} y ${g.b})?`, _baraja(gente).slice(0, need), impostor);
    });
  }

  for (const g of _baraja(generadores)) {
    const r = g(); if (r) return r;
  }
  return null;
}

/** Ronda de nPaneles paneles. Evita repetir el TIPO de pregunta dentro de la
 *  ronda (mientras haya tipos disponibles), nunca repite pregunta+respuesta,
 *  y no encadena dos preguntas iguales seguidas. */
export function generarRondaImpostor(nPaneles, N, dif, personas) {
  const paneles = [];
  const combosUsados = new Set();     // "texto|idImpostor"
  const tiposUsados = new Set();      // tipos ya usados en la ronda
  let tipoPrevio = "";
  for (let i = 0; i < nPaneles; i++) {
    let elegido = null, respaldo = null;
    for (let t = 0; t < 200; t++) {
      const c = construirPanel(N, dif, personas);
      if (!c) continue;
      const imp = c.cartas.find(x => x.impostor);
      const combo = c.texto + "|" + imp.id;
      if (combosUsados.has(combo)) continue;                 // misma pregunta+respuesta ya vista
      respaldo = respaldo || c;
      if (c.tipo === tipoPrevio && t < 120) continue;        // no encadenar el mismo tipo
      if (tiposUsados.has(c.tipo) && t < 100) continue;      // preferir un tipo nuevo en la ronda
      elegido = c; break;
    }
    elegido = elegido || respaldo;
    if (!elegido) return null;
    const imp = elegido.cartas.find(x => x.impostor);
    combosUsados.add(elegido.texto + "|" + imp.id);
    tiposUsados.add(elegido.tipo);
    tipoPrevio = elegido.tipo;
    paneles.push(elegido);
  }
  return paneles;
}

export function capacidadImpostor(N, dif, personas) {
  // ¿se puede construir al menos un panel de ese tamaño?
  for (let t = 0; t < 40; t++) if (construirPanel(N, dif, personas)) return true;
  return false;
}

